-- ------------------------------------------------------------
-- 30 ferdige modeller til galleriet (PrintFiksEB)
-- Kjør denne i Supabase -> SQL Editor etter schema.sql.
-- Trygg å kjøre flere ganger: modeller som allerede finnes hoppes over.
-- Bildene ligger i prosjektet under public/modeller/ og følger med på Vercel.
-- ------------------------------------------------------------

insert into public.products
  (code, name, description, details, tagline, highlights, price, image_url, images,
   material, weight_g, category, featured, sort)
select v.* from (values
  ('10412', 'Penneholder «Kube»', 'En firkantet penneholder med tung bunn, så den blir stående selv om du drar i pennen. Passer penner, blyanter, saks og linjal.', 'Holderen er 8 x 8 cm og 9 cm høy, med ekstra tykk bunn så den står støtt på pulten. Innsiden er åpen, så du kan ha både penner, blyanter, linjal og saks i samme holder. Vi printer den med solide vegger, så den tåler å bli dratt i og flyttet på hver dag. Si fra om du vil ha den høyere eller smalere, det koster ikke noe ekstra.', 'Enkel penneholder som ikke velter',
   array['8 x 8 x 9 cm', 'Tung bunn som ikke velter', 'Kan lages høyere eller smalere'], 99, '/modeller/penneholder-1.jpg', array['/modeller/penneholder-2.jpg', '/modeller/penneholder-3.jpg'], 'PLA', 45,
   'Kontor', false, 10),
  ('10538', 'Kabelholder til pultkanten (3-pk)', 'Tre små holdere som limes på pultkanten og holder ladekabelen, hodetelefonkabelen eller USB-kabelen på plass. Slutt på å fiske kabelen opp fra gulvet.', 'Du får tre holdere i pakken. De festes med dobbeltsidig tape (følger med) på kanten av pulten, nattbordet eller bak TV-benken. Sporet passer vanlige lade- og USB-kabler, og kabelen klikkes inn og ut uten at du må tre den gjennom. Trenger du flere enn tre, si fra så lager vi akkurat det antallet du vil ha.', 'Ladekabelen blir liggende på pulten',
   array['3 stk i pakken', 'Tape følger med', 'Passer vanlige lade- og USB-kabler'], 79, '/modeller/kabelholder-1.jpg', array['/modeller/kabelholder-2.jpg', '/modeller/kabelholder-3.jpg'], 'PLA', 18,
   'Kontor', false, 20),
  ('10627', 'Laderholder til stikkontakten', 'En liten hylle som henger på selve laderen i stikkontakten, så telefonen ikke ligger på gulvet mens den lader. Passer de fleste telefoner med og uten deksel.', 'Holderen tres over laderen og hviler mot veggen, så den tåler vekten av en vanlig telefon. Hullet passer standard norske ladere, og hyllen er dyp nok til telefon med deksel. Vi printer den i PETG fordi det tåler litt varme fra laderen bedre enn vanlig PLA. Har du en spesiell lader, ta et bilde og send oss, så tilpasser vi hullet.', 'Telefonen henger trygt mens den lader',
   array['Henger på laderen', 'Plass til telefon med deksel', 'PETG som tåler varme'], 69, '/modeller/laderholder-1.jpg', array['/modeller/laderholder-2.jpg', '/modeller/laderholder-3.jpg'], 'PETG', 25,
   'Hjem', false, 30),
  ('10744', 'Brilleholder til pulten', 'Et lite stativ som holder brillene trygt når du ikke bruker dem. Brillene legges over toppen med glassene ned i luften, så de ikke blir ripete.', 'Stativet er 12 cm høyt med bred fot, så det står stødig på pulten eller nattbordet. Toppen er myk i formen, slik at brillestengene ikke blir presset ut av stilling. Passer både lesebriller, solbriller og vanlige briller. Vi kan også lage en bredere variant hvis du har store solbriller.', 'En fast plass til brillene',
   array['12 cm høy', 'Bred fot som står stødig', 'Skåner glassene'], 89, '/modeller/brilleholder-1.jpg', array['/modeller/brilleholder-2.jpg', '/modeller/brilleholder-3.jpg'], 'PLA', 30,
   'Kontor', false, 40),
  ('10859', 'Visittkortholder', 'En skrå holder til visittkort på disken eller pulten. Kortene står i vinkel så folk ser dem med en gang og lett kan ta ett.', 'Holderen tar rundt 30 vanlige visittkort. Sporet er skrått, så kortene står fram og ikke faller sammen etter hvert som bunken blir mindre. Fin på en disk, i en butikk eller på en stand. Vi kan printe navnet eller logoen din i fronten hvis du vil, da legger vi på 100 kr for designjobben.', 'Kortene står pent fram',
   array['Plass til ca. 30 kort', 'Skrått spor så kortene står fram', 'Kan få navn eller logo i fronten'], 79, '/modeller/visittkortholder-1.jpg', array['/modeller/visittkortholder-2.jpg', '/modeller/visittkortholder-3.jpg'], 'PLA', 20,
   'Kontor', false, 50),
  ('10963', 'Dørstopper', 'En kileformet dørstopper som holder døra åpen uten å skli. Undersiden har riller som gir godt grep mot både parkett og laminat.', 'Kilen er printet massiv i PETG, som er seigere enn vanlig PLA og tåler å bli sparket bort og dratt fram hver dag. Rillene på undersiden gir feste mot glatt gulv, og den skrå formen gjør at den klemmer seg fast jo hardere døra presser. Passer vanlige innerdører. Trenger du en til en tung ytterdør, si fra, da printer vi en bredere variant.', 'Holder døra der du vil ha den',
   array['PETG som tåler hard bruk', 'Riller som gir grep', 'Passer vanlige innerdører'], 69, '/modeller/dorstopper-1.jpg', array['/modeller/dorstopper-2.jpg', '/modeller/dorstopper-3.jpg'], 'PETG', 35,
   'Hjem', false, 60),
  ('11078', 'Skuffeorganiserer (3-pk)', 'Tre åpne bokser i ulike størrelser som settes ned i skuffen og holder orden på småting. Bra til kjøkkenskuffen, kontorskuffen eller på badet.', 'Boksene er 5 cm dype og kommer i tre bredder, så de kan settes ved siden av hverandre eller inni hverandre. Kantene er glatte, så de ikke river i skuffen når du drar dem fram. Mål opp skuffen din og send oss målene, så printer vi settet i akkurat den størrelsen som fyller skuffen — det koster ikke noe ekstra så lenge det er innenfor vanlig størrelse.', 'Slutt på rotet i skuffen',
   array['3 bokser i ulike størrelser', '5 cm dype', 'Kan tilpasses skuffen din gratis'], 149, '/modeller/skuffeorganiserer-1.jpg', array['/modeller/skuffeorganiserer-2.jpg', '/modeller/skuffeorganiserer-3.jpg'], 'PLA', 120,
   'Oppbevaring', false, 70),
  ('11185', 'Bokstøtter (2-pk)', 'Et par L-formede bokstøtter med lang fot som går under bøkene. Vekten av bøkene holder støtten på plass, så de ikke sklir ut som billige metallstøtter gjør.', 'Foten er 10 cm lang og bare 3 mm tykk, så bøkene står rett ned på hyllen og skyver ikke støtten ut. Ryggen er 20 cm høy og tåler en full rekke med bøker. Du får to støtter i settet. Trenger du dem høyere fordi du har store bøker, si fra så printer vi dem etter dine mål.', 'To støtter som faktisk holder bøkene oppe',
   array['2 støtter i settet', '10 cm fot under bøkene', '20 cm høy rygg'], 199, '/modeller/bokstotter-1.jpg', array['/modeller/bokstotter-2.jpg', '/modeller/bokstotter-3.jpg'], 'PLA', 180,
   'Oppbevaring', false, 80),
  ('11294', 'Veggkroker (4-pk)', 'Enkle kroker som skrus eller limes på veggen. Tåler jakker, handlenett, ledninger og verktøy.', 'Hver krok har to skruehull, og du kan også bruke dobbeltsidig tape hvis du ikke vil skru i veggen. Vi printer dem i PETG med massiv krokdel, så de tåler et godt tak. En krok holder fint en tung vinterjakke når den er skrudd fast. Du får fire i pakken, og vi kan lage flere eller større kroker om du trenger det.', 'Fire kroker til gangen eller boden',
   array['4 kroker i pakken', 'Skrus eller limes', 'PETG, tåler tung jakke'], 99, '/modeller/veggkrok-1.jpg', array['/modeller/veggkrok-2.jpg', '/modeller/veggkrok-3.jpg'], 'PETG', 24,
   'Oppbevaring', false, 90),
  ('11347', 'Kabelklips til vegg (8-pk)', 'Åtte små klips som limes langs vegg, listverk eller bak TV-benken og holder ledningene på rekke. Kabelen klikkes inn, ikke tres gjennom.', 'Klipsene har åpent spor, så du kan ta kabelen ut igjen uten å trekke ut støpselet. De limes med dobbeltsidig tape som følger med. Passer ladekabler, nettverkskabler og strømledninger opp til 6 mm. Vi kan printe dem i en farge som ligner veggen din hvis du vil at de skal skjule seg litt.', 'Få ledningene bort fra gulvet',
   array['8 klips i pakken', 'Åpent spor, kabelen klikkes inn', 'Tape følger med'], 59, '/modeller/kabelklips-1.jpg', array['/modeller/kabelklips-2.jpg', '/modeller/kabelklips-3.jpg'], 'PLA', 16,
   'Oppbevaring', false, 100),
  ('11458', 'Fjernkontrollholder', 'En holder med to rom til fjernkontroller, så de slutter å forsvinne ned i sofaen. Står fint på sofabordet eller TV-benken.', 'Holderen har to rom, ett bredt og ett smalt, så både den store TV-fjernkontrollen og den lille til lydplanken får plass. Bunnen er lukket, så støv og fjernkontroller blir der de skal. Vil du ha tre rom, eller et rom til brillene ved siden av, sier du bare fra når du bestiller.', 'Alle fjernkontrollene på ett sted',
   array['To rom i ulik bredde', 'Lukket bunn', 'Kan lages med flere rom'], 99, '/modeller/fjernkontrollholder-1.jpg', array['/modeller/fjernkontrollholder-2.jpg', '/modeller/fjernkontrollholder-3.jpg'], 'PLA', 55,
   'Hjem', false, 110),
  ('11562', 'Oppbevaringsboks med lokk', 'En stabelbar boks med tettsittende lokk. Fin til skruer, perler, ladere, medisiner eller andre småting som ellers blir borte.', 'Boksen er 12 x 8 cm og 6 cm høy. Lokket har kant som klikker på plass, så det ikke faller av når du bærer boksen. Boksene kan stables oppå hverandre, så du kan bestille flere og bygge en liten stabel. Vi kan printe en etikett-plate på lokket med tekst hvis du vil merke innholdet.', 'Liten boks med lokk som sitter',
   array['12 x 8 x 6 cm', 'Lokk som klikker på plass', 'Kan stables'], 129, '/modeller/oppbevaringsboks-1.jpg', array['/modeller/oppbevaringsboks-2.jpg', '/modeller/oppbevaringsboks-3.jpg'], 'PLA', 95,
   'Oppbevaring', false, 120),
  ('11679', 'Knivholder til benken', 'En skrå knivholder med fire spor til de knivene du bruker mest. Sporene er åpne i bunnen, så vann renner ut og knivene tørker.', 'Holderen tar fire kniver opp til 20 cm blad, og står i vinkel så du får tak i håndtaket med en gang. Sporene er åpne nede, slik at vann ikke blir stående — det er der vanlige treblokker ryker. Vi printer den i PETG fordi det tåler oppvask i hånden og varme fra benken. Har du kniver med brede blad, send oss et bilde så justerer vi sporene.', 'Knivene ligger trygt og tørt',
   array['Plass til 4 kniver', 'Åpne spor så vannet renner ut', 'PETG, tåler kjøkkenbenken'], 199, '/modeller/knivholder-1.jpg', array['/modeller/knivholder-2.jpg', '/modeller/knivholder-3.jpg'], 'PETG', 140,
   'Kjøkken', true, 130),
  ('53417', 'Saksholder', 'En rund holder med tung bunn til saks, kjøkkensaks og annet spisst. Kan stå på benken eller skrus fast på innsiden av skapdøra.', 'Holderen er 10 cm høy og litt smalere nede, så den ikke velter når du drar saksa opp. Innsiden er åpen hele veien ned, så du kan skylle den under springen. Det følger med to skruehull i bunnen hvis du vil ha den fast på innsiden av en skapdør. Dette er modellen vi bruker som eksempel når vi viser hvordan du bestiller.', 'En plass til saksa som alltid blir borte',
   array['10 cm høy', 'Tung bunn', 'Kan skrus fast i skapdøra'], 99, '/modeller/saksholder-1.jpg', array['/modeller/saksholder-2.jpg', '/modeller/saksholder-3.jpg'], 'PLA', 40,
   'Kjøkken', false, 140),
  ('11784', 'Poseklips (6-pk)', 'Klips til chipsposer, brødposer og frysposer. De klemmer hardt nok til å holde tett, men er enkle å åpne med én hånd.', 'Du får seks klips i pakken, 8 cm brede. De er printet i PETG, som er mykt nok til å fjære uten å knekke — vanlig PLA sprekker etter noen måneder i kjøkkenskuffen. Klipsene tåler fryseren. Trenger du bredere klips til store poser, kan vi printe det i samme pakke.', 'Seks klips som faktisk holder posen igjen',
   array['6 klips i pakken', '8 cm brede', 'Tåler fryseren'], 69, '/modeller/poseklips-1.jpg', array['/modeller/poseklips-2.jpg', '/modeller/poseklips-3.jpg'], 'PETG', 22,
   'Kjøkken', false, 150),
  ('11893', 'Kaffekapsel-holder', 'Et lite tårn som tar rundt 24 kaffekapsler. Kapslene ligger i åpne spor, så du ser hvilke smaker du har igjen.', 'Tårnet er 30 cm høyt og har plass til 24 kapsler fordelt på seks etasjer. Bunnen er bred og tung, så det står stødig selv når det er halvtomt. Passer standard kapsler av Nespresso-typen. Har du en annen type kapsler, send oss målene, så printer vi sporene i riktig størrelse.', 'Kapslene synlig og på plass',
   array['Plass til ca. 24 kapsler', '30 cm høyt', 'Passer Nespresso-størrelse'], 149, '/modeller/kapselholder-1.jpg', array['/modeller/kapselholder-2.jpg', '/modeller/kapselholder-3.jpg'], 'PLA', 110,
   'Kjøkken', false, 160),
  ('11967', 'Glassbrikker (4-pk)', 'Runde glassbrikker med printet mønster i overflaten. Beskytter bordet mot kalde glass og varme kopper.', 'Brikkene er 10 cm i diameter med opphøyd kant, så kondens fra glasset blir liggende på brikken og ikke renner ut på bordet. Mønsteret kommer av selve printingen, så alle fire blir like. Tåler kalde glass og varme kopper, men ikke kokende kjeler rett fra platetoppen. Vil du ha dem i to forskjellige farger, er det bare å si fra.', 'Fire brikker med mønster',
   array['4 brikker, 10 cm', 'Opphøyd kant mot kondens', 'Kan lages i to farger'], 99, '/modeller/glassbrikker-1.jpg', array['/modeller/glassbrikker-2.jpg', '/modeller/glassbrikker-3.jpg'], 'PLA', 60,
   'Kjøkken', false, 170),
  ('12073', 'Eggeglass (2-pk)', 'Klassiske eggeglass med bred fot. Passer både små og store egg, og de står stødig selv når du hakker løs på toppen.', 'Du får to eggeglass i settet. Formen er litt trang oppe og vid nede, så egget sitter fast mens du åpner det. De tåler vanlig oppvask i hånden, men ikke oppvaskmaskin — der blir det for varmt for PLA. Vil du ha fire i stedet for to, koster det bare materialet ekstra.', 'To eggeglass som står støtt',
   array['2 stk i settet', 'Passer små og store egg', 'Håndvask, ikke maskin'], 69, '/modeller/eggeglass-1.jpg', array['/modeller/eggeglass-2.jpg', '/modeller/eggeglass-3.jpg'], 'PLA', 30,
   'Kjøkken', false, 180),
  ('12186', 'Tannbørsteholder til vegg', 'En holder med fire hull som limes på flisen eller speilet. Børstene henger fritt, så vannet renner av og det blir ikke sølepytt i bunnen.', 'Holderen festes med dobbeltsidig tape som tåler fukt, eller kan skrus hvis du heller vil det. Hullene passer både vanlige tannbørster og de fleste elektriske. Vi printer den i PETG fordi det tåler fukt og varme på badet bedre enn PLA. Trenger dere plass til fem eller seks børster, printer vi en lengre variant.', 'Børstene henger fritt og tørker',
   array['Plass til 4 børster', 'Tape som tåler fukt', 'PETG, laget for bad'], 99, '/modeller/tannborsteholder-1.jpg', array['/modeller/tannborsteholder-2.jpg', '/modeller/tannborsteholder-3.jpg'], 'PETG', 45,
   'Bad', false, 190),
  ('12295', 'Såpeskål med drenering', 'En skål med riller i bunnen som løfter såpa opp fra vannet. Såpestykket varer mye lenger når det får tørke mellom hver gang.', 'Rillene holder såpa over bunnen, og skålen heller lett mot den ene siden så vannet renner ut. Kanten er høy nok til at vannet ikke renner utover benken med en gang. Printet i PETG, som tåler fukt og varmt vann. Passer vanlige såpestykker, og vi kan lage en større variant til de store blokkene.', 'Såpa blir ikke liggende i vann',
   array['Riller som løfter såpa', 'Heller så vannet renner ut', 'PETG, tåler fukt'], 89, '/modeller/sapeskal-1.jpg', array['/modeller/sapeskal-2.jpg', '/modeller/sapeskal-3.jpg'], 'PETG', 50,
   'Bad', false, 200),
  ('12364', 'Dusjkroker (2-pk)', 'Kroker til dusjen, badet eller vaskerommet. Festes med tape som tåler vann, og holder håndkle, barberhøvel eller dusjsvamp.', 'Krokene har rund bakplate og myk bue, så håndkleet ikke får merker. Tapen som følger med er laget for fukt, men vent et døgn før du henger noe tungt i dem, slik at limet får satt seg. Printet i PETG, som ikke mykner av varmt vann slik PLA gjør. Du får to kroker i pakken.', 'To kroker som tåler fukt',
   array['2 kroker i pakken', 'Tape som tåler dusjen', 'PETG, mykner ikke av varmt vann'], 79, '/modeller/dusjkrok-1.jpg', array['/modeller/dusjkrok-2.jpg', '/modeller/dusjkrok-3.jpg'], 'PETG', 26,
   'Bad', false, 210),
  ('12478', 'Blomsterpotte 10 cm med fat', 'En potte på 10 cm med dreneringshull og eget fat under. Passer urter fra butikken rett i potten uten å plante om.', 'Potten har hull i bunnen og fatet fanger opp vannet, så du kan ha den på vinduskarmen uten å sette flekker. Innvendig mål passer vanlige plastpotter med urter fra dagligvarebutikken. Printet i PETG fordi det tåler sol i vinduskarmen uten å bli mykt. Vi lager den gjerne i 8, 12 eller 15 cm også, da endrer prisen seg litt etter størrelsen.', 'Potte og fat i ett sett',
   array['10 cm, med fat', 'Dreneringshull i bunnen', 'Tåler sol i vinduskarmen'], 129, '/modeller/blomsterpotte-1.jpg', array['/modeller/blomsterpotte-2.jpg', '/modeller/blomsterpotte-3.jpg'], 'PETG', 85,
   'Hage', true, 220),
  ('12589', 'Spiralvase', 'En høy vase med spiralmønster som kommer av selve printingen. Fin alene på bordet, eller med noen få stilker i.', 'Vasen er 22 cm høy og printet i ett stykke uten skjøter. Den er tett nok til vann, men vi anbefaler å sette et lite glass inni hvis den skal stå med vann i flere uker. Mønsteret vrir seg hele veien opp og ser forskjellig ut alt etter hvor lyset kommer fra. Vi kan printe den høyere eller slankere hvis du vil ha den til en bestemt plass.', 'Vase med vridd mønster',
   array['22 cm høy', 'Printet i ett stykke', 'Kan lages høyere eller slankere'], 149, '/modeller/vase-1.jpg', array['/modeller/vase-2.jpg', '/modeller/vase-3.jpg'], 'PETG', 95,
   'Hjem', false, 230),
  ('12693', 'Urteskilt til kjøkkenhagen (6-pk)', 'Skilt du stikker ned i jorda så du husker hva du sådde. Vi printer navnet rett inn i skiltet, så det ikke vaskes bort av regn.', 'Du får seks skilt i pakken, 14 cm høye med spiss nederst. Teksten er printet som opphøyde bokstaver, ikke skrevet på, så den blir stående ute hele sesongen. Send oss navnene når du bestiller — basilikum, gressløk, tomat, hva du vil. Printet i PETG, som tåler sol og regn bedre enn PLA.', 'Seks skilt med navnet du vil ha',
   array['6 skilt i pakken', 'Navnet printes inn i skiltet', 'PETG som tåler sol og regn'], 79, '/modeller/urteskilt-1.jpg', array['/modeller/urteskilt-2.jpg', '/modeller/urteskilt-3.jpg'], 'PETG', 18,
   'Hage', false, 240),
  ('12748', 'Terningtårn', 'Et tårn med skråplan inni, der terningene trilles ned og lander i brettet foran. Terningene blir på bordet, og ingen kan beskylde noen for å triksje med kastet.', 'Tårnet er 22 cm høyt med tre skråplan inni, som gir terningene nok sprett til at kastet blir tilfeldig. Brettet foran fanger opp terningene, og har kant hele veien rundt. Tåler alt fra vanlige sekssidige terninger til store D20. Vi kan printe det i to farger, for eksempel svart tårn og hvitt brett, si fra når du bestiller.', 'Ingen flere terninger på gulvet',
   array['22 cm høyt', 'Tre skråplan inni', 'Passer også store D20-terninger'], 249, '/modeller/terningtarn-1.jpg', array['/modeller/terningtarn-2.jpg', '/modeller/terningtarn-3.jpg'], 'PLA', 190,
   'Gaming', true, 250),
  ('12857', 'Kortholder til brettspill (4-pk)', 'Skrå kortholdere som gjør at du slipper å holde kortene i hånda. Fint for spillekvelder, og et must om du spiller med noen som har vondt i hendene.', 'Hver holder har to spor og tar rundt 15 kort. Sporene er skrå, så kortene står fram uten at naboen ser dem. De er 16 cm brede og stabelbare, så de ikke tar plass i spillskapet. Du får fire i settet — trenger dere seks fordi dere er en stor gjeng, printer vi det.', 'Fire holdere så alle ser kortene sine',
   array['4 holdere i settet', 'To spor, ca. 15 kort per holder', 'Stabelbare'], 129, '/modeller/kortholder-1.jpg', array['/modeller/kortholder-2.jpg', '/modeller/kortholder-3.jpg'], 'PLA', 70,
   'Gaming', false, 260),
  ('12961', 'Kontrollerstativ', 'Et stativ til PlayStation-, Xbox- eller Switch Pro-kontrolleren. Bred fot som står stødig, og mykt opplegg så kontrolleren ikke får riper.', 'Stativet er 18 cm høyt med tung, bred fot. Toppen er formet etter undersiden av kontrolleren, så den ligger stabilt og ikke sklir av. Passer PlayStation, Xbox og Switch Pro — si fra hvilken du har, så printer vi toppen riktig. Vil du ha plass til to kontrollere, lager vi en dobbel variant.', 'Kontrolleren står framme, ikke i sofaen',
   array['18 cm høyt', 'Passer PS, Xbox og Switch Pro', 'Kan lages til to kontrollere'], 179, '/modeller/kontrollerstativ-1.jpg', array['/modeller/kontrollerstativ-2.jpg', '/modeller/kontrollerstativ-3.jpg'], 'PLA', 120,
   'Gaming', false, 270),
  ('13074', 'Nøkkelring med navn', 'En liten nøkkelring med navnet ditt printet inn. Fin som gave, eller til å skille nøklene i familien fra hverandre.', 'Nøkkelringen er 5 cm lang, og teksten printes som opphøyde bokstaver i selve plasten — den slites ikke bort slik en merkelapp gjør. Ringen i metall følger med. Du velger farge og hva det skal stå: navn, dato, «hytta», «bod». Skal du ha mange like til et lag eller en klasse, gi oss beskjed, da blir stykkprisen lavere.', 'Navn, dato eller det du vil ha',
   array['5 cm, metallring følger med', 'Teksten printes inn i plasten', 'Billigere ved mange like'], 49, '/modeller/nokkelring-1.jpg', array['/modeller/nokkelring-2.jpg', '/modeller/nokkelring-3.jpg'], 'PETG', 8,
   'Gaver', true, 280),
  ('13185', 'Navneskilt til døra', 'Et skilt med navnet deres, printet i opphøyde bokstaver. Passer til ytterdøra, postkassen eller døra til rommet.', 'Skiltet er 15 x 6 cm med skruehull i hjørnene, og du kan også bruke dobbeltsidig tape. Bokstavene er printet i en annen farge enn bakgrunnen, så navnet er lett å lese på avstand. Vi printer i PETG som tåler sol og regn, så det kan henge ute. Vil du ha større skilt eller flere linjer med tekst, ordner vi det.', 'Skilt til ytterdøra eller rommet',
   array['15 x 6 cm', 'Opphøyde bokstaver i egen farge', 'PETG, tåler å henge ute'], 99, '/modeller/navneskilt-1.jpg', array['/modeller/navneskilt-2.jpg', '/modeller/navneskilt-3.jpg'], 'PETG', 35,
   'Gaver', false, 290),
  ('13296', 'Julestjerne til treet', 'En stjerne med mønster i overflaten, med hull til snor. Fin i juletreet, i vinduet eller som pynt på en gavepakke.', 'Stjernen er 9 cm bred og tynn nok til å henge lett i en gren. Mønsteret kommer av selve printingen og fanger lyset fra julelysene fint. Snor følger med. Bestiller du flere, kan vi printe dem i forskjellige farger, og vi kan sette navn eller årstall på baksiden hvis den skal være en gave.', 'Pynt som varer år etter år',
   array['9 cm, snor følger med', 'Kan fås i flere farger', 'Navn eller årstall på baksiden'], 69, '/modeller/julestjerne-1.jpg', array['/modeller/julestjerne-2.jpg', '/modeller/julestjerne-3.jpg'], 'PLA', 14,
   'Gaver', false, 300)
) as v(code, name, description, details, tagline, highlights, price, image_url, images,
